import {
  getMessaging,
  getToken,
  onMessage,
  isSupported,
} from "firebase/messaging";
import { getFunctions, httpsCallable } from "firebase/functions";
import {
  doc,
  setDoc,
  updateDoc,
  getDoc,
  arrayRemove,
  serverTimestamp,
  arrayUnion,
  deleteField,
  addDoc,
  collection,
} from "firebase/firestore";
import { app, db, auth } from "./firebase";

// --------------------------------------
// client-side event logging (for debugging on devices without devtools)
// writes a small document to Firestore; used when notifications stop working
export const logClientEvent = async (event, detail = {}) => {
  try {
    const logsRef = collection(db, "clientLogs");
    await addDoc(logsRef, {
      event,
      detail,
      timestamp: serverTimestamp(),
    });
  } catch (err) {
    console.warn("logClientEvent failed:", err);
  }
};
